// Renders the app's screens with made-up demo data and saves them as PNGs for
// the documentation (docs/assets/screenshots/).
//
//   flutter test --update-goldens screenshot_test/
//
// Runs without a phone or emulator: Flutter draws every screen in memory. The
// demo class comes from docs/demo/ (generated by tool/demo/generate_demo.py),
// read through the app's real CSV importer. Kept out of test/ so the normal
// `flutter test` run doesn't compare screenshots.
import 'dart:async';
import 'dart:io';
import 'dart:math';

import 'package:flutter/material.dart';
import 'package:flutter/services.dart';
