import 'package:nameit/ui/games/flashcards_game.dart';
import 'package:nameit/ui/games/game_common.dart';
import 'package:nameit/ui/games/memory_game.dart';
import 'package:nameit/ui/games/millionenshow_game.dart';
import 'package:nameit/ui/games/reveal_game.dart';
import 'package:nameit/ui/games/type_game.dart';
import 'package:nameit/ui/screens/class_screen.dart';
