/// Language of the screenshots: 'en' or 'de'. Override with
/// `--dart-define=SHOT_LOCALE=de`.
const locale = String.fromEnvironment('SHOT_LOCALE', defaultValue: 'en');

/// Phone screen: 393 × 852 logical pixels (a typical current phone) at 2.5×
/// → 983 × 2130 PNGs.
const logicalSize = Size(393, 852);
const pixelRatio = 2.5;

/// Layout overflows found while rendering. Reported at the end instead of
/// failing the run, so one cut-off label doesn't block all screenshots.
final _layoutWarnings = <String>{};

final _shotKey = GlobalKey();

void main() {
  late Directory tmp;

  setUpAll(() async {
    tmp = Directory.systemTemp.createTempSync('nameit_shots');
    PathProviderPlatform.instance = _FakePaths(tmp.path);
    // No saved WebUntis login, so the import screen shows its first page.
    TestWidgetsFlutterBinding.ensureInitialized();
    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger.setMockMethodCallHandler(
      const MethodChannel('plugins.it_nomads.com/flutter_secure_storage'),
      (call) async => null,
    );
    await _loadFonts();
  });

  tearDownAll(() => tmp.deleteSync(recursive: true));

  testWidgets(timeout: const Timeout(Duration(minutes: 8)), 'documentation screenshots', (tester) async {
    tester.view
      ..physicalSize = logicalSize * pixelRatio
      ..devicePixelRatio = pixelRatio;
    addTearDown(tester.view.reset);

    final reportError = FlutterError.onError;
    FlutterError.onError = (details) {
      final msg = details.exceptionAsString();
      if (msg.contains('overflowed by')) {
        _layoutWarnings.add('${msg.split('\n').first} – ${details.context?.toDescription() ?? ''}'
            '${_currentShot.isEmpty ? '' : ' (screenshot "$_currentShot")'}');
        return;
      }
      reportError?.call(details);
    };

    final store = AppStore();
    await tester.runAsync(store.load);

    // ---------------------------------------------------------------- empty app
    await shoot(tester, store, const HomeScreen(), 'welcome');

    // ---------------------------------------------------------------- demo data
    await tester.runAsync(() => _seed(store));
    await tester.runAsync(() => _decodePhotos(store));
    _log('demo data ready: ${store.students.length} students');
    final cls3b = store.classes.firstWhere((c) => c.name == '3B');
    final pool = store.studentsOf(cls3b.id).where((s) => s.hasPhoto).toList();

    await shoot(tester, store, const HomeScreen(), 'home');
    await shoot(tester, store, ClassScreen(classId: cls3b.id), 'class');
    await shoot(tester, store, ClassScreen(classId: cls3b.id), 'game-picker', before: (t) async {
      await t.tap(find.text(_t('Play', 'Spielen')));
    });
    final lena = pool.firstWhere((s) => s.firstName == 'Lena');
    await shoot(tester, store, StudentScreen(classId: cls3b.id, student: lena), 'student');

    // Stats is a long page: render it taller so badges are on the picture.
    tester.view.physicalSize = Size(logicalSize.width, 1700) * pixelRatio;
    await shoot(tester, store, const StatsScreen(), 'stats');
    tester.view.physicalSize = logicalSize * pixelRatio;

    await shoot(tester, store, const SettingsScreen(), 'settings');

    await shoot(tester, store, const ImportScreen(), 'import-webuntis');
    await shoot(tester, store, const ImportScreen(), 'import-file', before: (t) async {
      await t.tap(find.text(_t('File', 'Datei')));
    });
    await shoot(tester, store, const ImportScreen(), 'import-manual', before: (t) async {
      await t.tap(find.text(_t('Manual', 'Manuell')));
    });

    // ---------------------------------------------------------------- games
    await shoot(tester, store, MillionenshowGame(classId: cls3b.id, pool: pool), 'game-millionaire');
    await shoot(tester, store, MemoryGame(classId: cls3b.id, pool: pool), 'game-memory', before: (t) async {
      final tiles = find.byWidgetPredicate((w) => w.runtimeType.toString() == '_MemoryTile');
      await t.tap(tiles.at(1));
      await t.pump(const Duration(milliseconds: 50));
      await t.tap(tiles.at(6));
    }, wait: const Duration(milliseconds: 200));
    await shoot(tester, store, FaceFinderGame(classId: cls3b.id, pool: pool), 'game-who-is-it');
    await shoot(tester, store, BlitzGame(classId: cls3b.id, pool: pool), 'game-blitz');
    await shoot(tester, store, RevealGame(classId: cls3b.id, pool: pool), 'game-reveal',
        wait: const Duration(milliseconds: 4200));
    await shoot(tester, store, TypeGame(classId: cls3b.id, pool: pool), 'game-type', before: (t) async {
      await t.enterText(find.byType(TextField), 'Le');
    });
    await shoot(tester, store, FlashcardsGame(classId: cls3b.id, pool: pool), 'game-flashcards', before: (t) async {
      await t.tap(find.text(_t('Flip', 'Umdrehen')));
    });

    final missed = pool.where((s) => s.level == 0).take(2).toList();
    await shoot(
      tester,
      store,
      ResultScreen(
        result: GameResult(
          modeTitleKey: 'gMillion',
          correct: 12,
          total: 15,
          xp: 240,
          missed: missed,
          headline: '€ 150.000',
          score: 150000,
        ),
        classId: cls3b.id,
        pool: pool,
        newBadges: [badgeById('streak7')],
      ),
      'result',
    );

    // ---------------------------------------------------------------- dark mode
    tester.platformDispatcher.platformBrightnessTestValue = Brightness.dark;
    await shoot(tester, store, const HomeScreen(), 'home-dark');
    await shoot(tester, store, ClassScreen(classId: cls3b.id), 'class-dark');
    tester.platformDispatcher.clearPlatformBrightnessTestValue();

    FlutterError.onError = reportError;
    if (_layoutWarnings.isNotEmpty) {
      // Shown as warnings on the GitHub Actions run.
      for (final w in _layoutWarnings) {
        // ignore: avoid_print
        print('::warning title=Layout overflow::$w');
      }
    }
  });
}

String _currentShot = '';

final _clock = Stopwatch()..start();

// ignore: avoid_print
void _log(String msg) => print('[${(_clock.elapsedMilliseconds / 1000).toStringAsFixed(1)} s] $msg');

String _t(String en, String de) => locale == 'de' ? de : en;

/// Pumps [screen] in a fresh app, optionally interacts, and saves the picture.
Future<void> shoot(
  WidgetTester tester,
  AppStore store,
  Widget screen,
  String name, {
  Future<void> Function(WidgetTester)? before,
  Duration wait = const Duration(milliseconds: 1200),
}) async {
  _currentShot = name;
  _log('rendering $name');
  // A new app per screenshot, so routes and state never leak between pictures.
  await tester.pumpWidget(const SizedBox());
  await tester.pumpWidget(ChangeNotifierProvider.value(
    value: store,
    child: RepaintBoundary(
      key: _shotKey,
      child: MaterialApp(
        key: UniqueKey(),
        title: 'nameIT',
        debugShowCheckedModeBanner: false,
        theme: AppTheme.light(),
        darkTheme: AppTheme.dark(),
        locale: const Locale(locale),
        supportedLocales: const [Locale('de'), Locale('en')],
        localizationsDelegates: const [
          GlobalMaterialLocalizations.delegate,
          GlobalWidgetsLocalizations.delegate,
          GlobalCupertinoLocalizations.delegate,
        ],
        home: screen,
      ),
    ),
  ));
  await _settle(tester, const Duration(milliseconds: 600));
  if (before != null) {
    await before(tester);
    await _settle(tester, wait);
  } else {
    await _settle(tester, wait);
  }
  await expectLater(find.byKey(_shotKey), matchesGoldenFile('../docs/assets/screenshots/$name.png'));

  // Let delayed game callbacks finish while the screen is still mounted.
  await tester.pump(const Duration(seconds: 2));
  await tester.pumpWidget(const SizedBox());
  await tester.pump(const Duration(seconds: 2));
}

/// Advances time in small steps (games run timers, so pumpAndSettle would never
/// return). Photos are already decoded (see [_decodePhotos]), so they appear
/// in the first frame.
Future<void> _settle(WidgetTester tester, Duration d) async {
  const steps = 10;
  for (var i = 0; i < steps; i++) {
    await tester.pump(d ~/ steps);
  }
}

/// Decodes every student photo into Flutter's image cache with real time.
/// Loading them from inside a widget test's fake clock would never finish;
/// from the cache, Image.file shows them immediately.
Future<void> _decodePhotos(AppStore store) async {
  for (final s in store.students) {
    final file = store.photoOf(s);
    if (file == null) continue;
    final done = Completer<void>();
    final stream = FileImage(file).resolve(ImageConfiguration.empty);
    late final ImageStreamListener listener;
    listener = ImageStreamListener(
      (_, _) {
        if (!done.isCompleted) done.complete();
      },
      onError: (e, _) {
        if (!done.isCompleted) done.completeError(e);
      },
    );
    stream.addListener(listener);
    await done.future.timeout(const Duration(seconds: 20));
    // Keep the listener: an image with a listener stays in the cache.
  }
}

/// Imports docs/demo/demo-classes.csv with the app's own importer, attaches the
/// avatar of every student and fills in believable learning progress.
Future<void> _seed(AppStore store) async {
  final csv = File('docs/demo/demo-classes.csv');
  final parsed = FileImporter.parse('demo-classes.csv', await csv.readAsBytes());
  final photoOf = <String, String>{};
  for (final line in (await csv.readAsLines()).skip(1)) {
    final c = line.split(';');
    photoOf['${c[2]} ${c[1]}'] = c[3];
  }

  // Every new year or class saves the data file; give each save time to
  // finish so two writes never race for the same temp file.
  Future<void> saved() => Future<void>.delayed(const Duration(milliseconds: 300));
  final year = store.addYear(defaultYearName());
  await saved();
  final classes = <String, SchoolClass>{};
  for (final name in parsed.rows.map((r) => r.className!).toSet()) {
    classes[name] = store.addClass(year.id, name);
    await saved();
  }
  for (final r in parsed.rows) {
    final cls = classes[r.className!]!;
    final s = store.upsertStudent(classId: cls.id, firstName: r.firstName, lastName: r.lastName, notify: false);
    final photo = File('docs/demo/avatars/${photoOf['${r.firstName} ${r.lastName}']}');
    await store.setPhoto(s, await photo.readAsBytes(), notify: false);
  }

  // Progress: 3B well practised, 4A just started.
  final rnd = Random(7);
  final now = DateTime.now();
  for (final s in store.students) {
    final is3b = store.classById(s.classId)!.name == '3B';
    final roll = rnd.nextDouble();
    s.level = is3b
        ? (roll < 0.4 ? 5 : roll < 0.8 ? 1 + rnd.nextInt(4) : 0)
        : (roll < 0.15 ? 2 + rnd.nextInt(2) : 0);
    s.correct = s.level * 2 + rnd.nextInt(3);
    s.wrong = s.level == 5 ? rnd.nextInt(2) : 1 + rnd.nextInt(4);
    s.lastSeen = now.subtract(Duration(hours: rnd.nextInt(120)));
  }

  String day(int ago) {
    final d = now.subtract(Duration(days: ago));
    return '${d.year}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
  }

  for (var ago = 0; ago < 14; ago++) {
    if (ago == 7 || ago == 10 || ago == 11) continue; // a few days off
    final answers = 12 + rnd.nextInt(40);
    store.days[day(ago)] = [answers, (answers * (0.65 + rnd.nextDouble() * 0.3)).round()];
  }
  store
    ..xp = 2340
    ..streak = 7
    ..bestStreak = 9
    ..lastPlayedDay = day(0);
  store.gamesByMode.addAll({'gMillion': 6, 'gMemory': 4, 'gFinder': 3, 'gBlitz': 5, 'gCards': 2});
  store.unlockedBadges.addAll({
    'firstGame': day(13),
    'streak3': day(4),
    'streak7': day(0),
    'perfect': day(9),
    'memory': day(5),
    'blitz': day(2),
  });
  store.commit();
  // Let the data file finish writing before the next picture.
  await Future<void>.delayed(const Duration(milliseconds: 200));
}

/// Real fonts instead of the test font (which draws every letter as a box).
/// Roboto and the Material icons ship with the Flutter SDK.
Future<void> _loadFonts() async {
  var root = Platform.environment['FLUTTER_ROOT'];
  // flutter_tester lives in <root>/bin/cache/artifacts/engine/<platform>/.
  root ??= File(Platform.resolvedExecutable).parent.parent.parent.parent.parent.parent.path;
  final dir = Directory('$root/bin/cache/artifacts/material_fonts');
  if (!dir.existsSync()) throw StateError('Fonts not found in ${dir.path}');

  final roboto = FontLoader('Roboto');
  // Text styles without a font family use the platform font on a phone, but
  // the box-drawing test font ('FlutterTest') in tests. Roboto replaces it.
  final fallback = FontLoader('FlutterTest');
  final icons = FontLoader('MaterialIcons');
  for (final f in dir.listSync().whereType<File>()) {
    final n = f.uri.pathSegments.last.toLowerCase();
    final bytes = f.readAsBytes().then((b) => ByteData.sublistView(b));
    if (n.startsWith('roboto') && !n.contains('mono') && !n.contains('condensed') && !n.contains('slab')) {
      roboto.addFont(bytes);
      fallback.addFont(bytes);
    } else if (n.startsWith('materialicons')) {
      icons.addFont(bytes);
    }
  }
  await roboto.load();
  await fallback.load();
  await icons.load();
}

class _FakePaths extends PathProviderPlatform with MockPlatformInterfaceMixin {
  _FakePaths(this.path);
  final String path;

  @override
  Future<String?> getApplicationDocumentsPath() async => path;
  @override
  Future<String?> getApplicationSupportPath() async => path;
  @override
  Future<String?> getTemporaryPath() async => path;
}
